                      <button type="button" className="btn btn--icon btn--danger" aria-label={`Remove ${cal.name}`} onClick={() => removeCalendar(entry.calendar_id)}>
                        <span className="material-symbols-outlined" style={{ fontSize: "18px" }}>close</span>
                      </button>
                    </div>
                  </li>;
                })}
