            "SELECT recurrence_rule FROM events WHERE id = ? AND calendar_id = ?",
        )
        .bind(resource.event_id)
        .bind(calendar.calendar_id)
        .fetch_optional(accounts.pool())
        .await
        .unwrap_or(None);
        if incoming
            .rrule
            .as_ref()
            .is_some_and(|rule| Some(rule) != current_rule.as_ref())
